From e1021ee26c05c889c99b7f7534a110bc20a11012 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:34:04 +0100
Subject: [PATCH] KFileItem: show the link emblem on all app launchers

Launchers only got the link emblem when the .desktop file happened to be
a symlink, so copies made by apps like Steam looked like plain files. Any
desktop file with an Exec key now gets the link emblem as well.

BUG: 493050
---
 src/core/kfileitem.cpp | 14 ++++++++++----
 1 file changed, 10 insertions(+), 4 deletions(-)

diff --git a/src/core/kfileitem.cpp b/src/core/kfileitem.cpp
index 7d6ebba59..92a9e810c 100644
--- a/src/core/kfileitem.cpp
+++ b/src/core/kfileitem.cpp
@@ -1347,10 +1347,16 @@ QStringList KFileItem::overlays() const
         KDesktopFile cfg(localPath());
         const KConfigGroup group = cfg.desktopGroup();

-        // Add a warning emblem if this is an executable desktop file
-        // which is untrusted.
-        if (group.hasKey("Exec") && !KDesktopFile::isAuthorizedDesktopFile(localPath())) {
-            names.append(QStringLiteral("emblem-important"));
+        if (group.hasKey("Exec")) {
+            // Add link emblem anyway since it's a "link" to launch this app
+            if (!names.contains(QStringLiteral("emblem-symbolic-link"))) {
+                names.append(QStringLiteral("emblem-symbolic-link"));
+            }
+            // Add a warning emblem if this is an executable desktop file
+            // which is untrusted.
+            if (!KDesktopFile::isAuthorizedDesktopFile(localPath())) {
+                names.append(QStringLiteral("emblem-important"));
+            }
         }
     }

